# -*- coding: utf-8 -*-
"""Physics I (PHY1.001) - Mechanics: chapter 3 Work, energy and momentum; chapter 4 Circular motion and rotation.
Sources: Mechanics tutorial Part 4 (momentum, work, energy, power), Part 5 (circular motion), Lectures 4 and 5."""
import math
from phys_common import *
import figs

P4 = "Mechanics tutorial Part 4"
P5 = "Mechanics tutorial Part 5"
GEN = lambda s: "Generated, same style as: " + s

# =============================================================================================== chapter 3
def ch3(B):
    c = "c3"
    # ---------------------------------------------------------------- momentum and collisions: concepts
    mcq_pick(B, c, "Momentum and collisions", 1, "Which statement correctly describes the principle of conservation of momentum?",
             ["Momentum is conserved only in elastic collisions", "Momentum is conserved by every body in a collision", "Momentum of a system is conserved provided no external force acts on it", "Momentum is the product of mass and velocity"], 2,
             ex("For an isolated system the total momentum is constant in ALL collisions (elastic or not). The individual bodies exchange momentum, so a single body does not conserve its own.", "Option 4 defines momentum; it does not state the principle."), P4 + ", Q1", "src")
    mcq_pick(B, c, "Momentum and collisions", 1, "In a collision between two steel balls suspended on strings (a nearly elastic collision), which quantities are conserved?",
             ["kinetic energy, total energy and momentum", "kinetic energy and momentum only", "kinetic energy and total energy only", "total energy and momentum only"], 0,
             ex("Elastic collision: momentum, kinetic energy and (as always) total energy are conserved. In an inelastic collision kinetic energy would be partly converted to heat or deformation."), P4 + ", Q3", "src")
    mcq_pick(B, c, "Momentum and collisions", 2, "Two spheres of equal mass $m$ move towards each other with speed $v$ and collide head-on elastically. Which statement is correct?",
             ["The spheres stick together", "The total kinetic energy after impact is $mv^2$", "The total kinetic energy before impact is zero", "The total momentum before impact is $2mv$"], 1,
             ex("Total momentum before $=mv-mv=0$ (so option 4 is wrong). Total kinetic energy before $=2\\cdot\\tfrac12mv^2=mv^2$, and the collision is elastic, so it is $mv^2$ afterwards too (the spheres simply reverse)."), P4 + ", Q4", "src")
    mcq_pick(B, c, "Momentum and collisions", 2, "A body initially at rest explodes into two parts of masses $M_1$ and $M_2$ that move apart with speeds $v_1$ and $v_2$. What is $v_1/v_2$?", ["$M_1/M_2$", "$M_2/M_1$", "$\\sqrt{M_1/M_2}$", "$\\sqrt{M_2/M_1}$"], 1,
             ex("Initial momentum zero: $M_1v_1=M_2v_2\\Rightarrow\\dfrac{v_1}{v_2}=\\dfrac{M_2}{M_1}$. The lighter piece moves faster."), P4 + ", Q5", "src")
    mcq_pick(B, c, "Momentum and collisions", 2, "A particle of mass $m$ and velocity $u$ collides head-on and elastically with a stationary particle of mass $M$. What is the velocity of $M$ afterwards?", ["$u$", "$mu/M$", "$\\dfrac{2mu}{M+m}$", "$\\dfrac{(M-m)u}{M+m}$"], 2,
             ex("Momentum: $mu=mv_1+Mv_2$. Elastic: $u=v_2-v_1$ (relative speed of approach = relative speed of separation).", "Eliminating $v_1$: $v_2=\\dfrac{2mu}{M+m}$. The expression $\\dfrac{(M-m)u}{M+m}$ is $-v_1$ in magnitude, the velocity of the incoming particle."), P4 + ", Q2", "src")
    # numbers for that formula, with the second equation as a check
    for m, M, u in [(2.0, 6.0, 8.0), (1.5, 1.5, 4.0), (3.0, 1.0, 6.0)]:
        v2 = 2 * m * u / (m + M); v1 = (m - M) * u / (m + M)
        check(m * u, m * v1 + M * v2); check(0.5 * m * u * u, 0.5 * m * v1 ** 2 + 0.5 * M * v2 ** 2)
        mcq_num(B, c, "Momentum and collisions", 2, "A %s kg cart moving at %s m/s collides head-on and elastically with a stationary %s kg cart. What is the velocity of the second cart after the collision?" % (sci(m), sci(u), sci(M)),
                v2, [u, m * u / M, (M - m) * u / (m + M), m * u / (m + M), u / 2, 2 * u], "m/s", ex("$v_2=\\dfrac{2m u}{m+M}=\\dfrac{2(%s)(%s)}{%s}=%s\\,\\mathrm{m/s}$." % (sci(m), sci(u), sci(m + M), sci(v2)), "First cart: $v_1=\\dfrac{m-M}{m+M}u=%s\\,\\mathrm{m/s}$; momentum and kinetic energy are both conserved." % sci(v1)), GEN(P4 + ", Q2"), "gen", sig=3)
    # sphere on a string hits block 4m (Q6)
    mcq_text(B, c, "Momentum and collisions", 3, "A sphere of mass $m$ on a string of length $\\ell$ is released from the horizontal position and strikes, at the bottom, a block of mass $4m$ at rest on a smooth table (perfectly elastic collision). The velocity of the block just after the collision is",
             "$\\dfrac25\\sqrt{2g\\ell}$ in the direction of the sphere's motion", ["$\\dfrac35\\sqrt{2g\\ell}$ in the direction of the sphere's motion", "$\\sqrt{2g\\ell}$ in the direction of the sphere's motion", "$\\dfrac25\\sqrt{2g\\ell}$ opposite to the sphere's motion"],
             ex("Swing: $mg\\ell=\\tfrac12mv^2\\Rightarrow v=\\sqrt{2g\\ell}$.", "Elastic collision with $M=4m$: $v_M=\\dfrac{2m}{m+4m}v=\\dfrac25\\sqrt{2g\\ell}$ and the sphere rebounds with $\\dfrac{m-4m}{5m}v=-\\dfrac35\\sqrt{2g\\ell}$.", "Check: momentum $m v=m(-\\tfrac35v)+4m(\\tfrac25v)=m v$."), P4 + ", Q6", "src")
    # Q7 two cars sticking
    m1, v1, m2, vf = 2150.0, 10.0, 3250.0, 5.22
    v2 = ((m1 + m2) * vf - m1 * v1) / m2
    dK = 0.5 * m1 * v1 ** 2 + 0.5 * m2 * v2 ** 2 - 0.5 * (m1 + m2) * vf ** 2
    check(dK, 0.5 * m1 * m2 / (m1 + m2) * (v1 - v2) ** 2)
    mcq_num(B, c, "Momentum and collisions", 3, "A $2150\\,\\mathrm{kg}$ car moving east at $10.0\\,\\mathrm{m/s}$ collides with a $3250\\,\\mathrm{kg}$ car also moving east. The cars stick together and move at $5.22\\,\\mathrm{m/s}$. What was the velocity of the $3250\\,\\mathrm{kg}$ car before the collision?",
            v2, [vf, (m1 * v1 + m2 * vf) / (m1 + m2), 10.0 - vf, (v1 + vf) / 2], "m/s", ex("Momentum conservation: $m_1v_1+m_2v_2=(m_1+m_2)v_f$.", "$v_2=\\dfrac{5400(5.22)-2150(10.0)}{3250}=2.06\\,\\mathrm{m/s}$ (east)."), P4 + ", Q7(a)", sig=3)
    mcq_num(B, c, "Momentum and collisions", 3, "The cars of the previous problem ($2150\\,\\mathrm{kg}$ at $10.0\\,\\mathrm{m/s}$ and $3250\\,\\mathrm{kg}$ at $2.06\\,\\mathrm{m/s}$) stick together and move off at $5.22\\,\\mathrm{m/s}$. How much kinetic energy is lost?",
            dK, [dK / 2, 0.5 * (m1 + m2) * vf ** 2, 0.5 * m1 * v1 ** 2, 0.5 * m2 * v2 ** 2], "J", ex("Before: $\\tfrac12(2150)(10.0)^2+\\tfrac12(3250)(2.058)^2=1.075\\times10^5+6.88\\times10^3=1.144\\times10^5\\,\\mathrm{J}$.", "After: $\\tfrac12(5400)(5.22)^2=7.36\\times10^4\\,\\mathrm{J}$.", "Loss $\\approx4.1\\times10^4\\,\\mathrm{J}$. Check with $\\Delta K=\\dfrac{m_1m_2}{2(m_1+m_2)}(v_1-v_2)^2=4.1\\times10^4\\,\\mathrm{J}$."), P4 + ", Q7(b)", sig=2)
    # Q8 decay into three particles
    M0, m_a, m_b = 17.0e-27, 5.0e-27, 8.4e-27
    m_c = M0 - m_a - m_b; px = -m_b * 4.0e6; py = -m_a * 6.0e6
    v_c = math.hypot(px, py) / m_c; ang = math.degrees(math.atan2(py, px)) % 360
    mcq_num(B, c, "Momentum and collisions", 3, "An unstable nucleus of mass $17.0\\times10^{-27}\\,\\mathrm{kg}$ at rest disintegrates into three particles. One ($5.0\\times10^{-27}\\,\\mathrm{kg}$) moves along $+y$ at $6.0\\times10^{6}\\,\\mathrm{m/s}$; another ($8.4\\times10^{-27}\\,\\mathrm{kg}$) moves along $+x$ at $4.0\\times10^{6}\\,\\mathrm{m/s}$. What is the speed of the third particle?",
            v_c, [v_c / 2, math.hypot(6.0e6, 4.0e6), 6.0e6 + 4.0e6, math.hypot(px, py) / (m_a + m_b)], "m/s", ex("Third mass: $17.0-5.0-8.4=3.6\\times10^{-27}\\,\\mathrm{kg}$.", "Momentum components of the third particle: $p_x=-(8.4\\times10^{-27})(4.0\\times10^6)=-3.36\\times10^{-20}$, $p_y=-(5.0\\times10^{-27})(6.0\\times10^6)=-3.0\\times10^{-20}\\,\\mathrm{kg\\,m/s}$.", "$|p|=4.50\\times10^{-20}$, so $v=\\dfrac{4.50\\times10^{-20}}{3.6\\times10^{-27}}=1.25\\times10^{7}\\,\\mathrm{m/s}$, at $%s^\\circ$ from $+x$ (third quadrant)." % sci(ang, 3)), P4 + ", Q8", sig=3)
    # Q9 bullet in block
    m, M, v = 0.012, 5.2, 1.7
    vb = (m + M) * v / m; frac = M / (m + M)
    check(1 - 0.5 * (m + M) * v ** 2 / (0.5 * m * vb ** 2), frac)
    mcq_num(B, c, "Momentum and collisions", 2, "A $12\\,\\mathrm{g}$ bullet strikes a stationary $5.2\\,\\mathrm{kg}$ wooden block on a frictionless surface and embeds in it; block plus bullet move at $1.7\\,\\mathrm{m/s}$. What was the speed of the bullet?", vb, [m * v / M, v * M, v, vb / 2], "m/s", ex("$mv_b=(m+M)v\\Rightarrow v_b=\\dfrac{(0.012+5.2)(1.7)}{0.012}=7.4\\times10^2\\,\\mathrm{m/s}$. Convert $12\\,\\mathrm{g}=0.012\\,\\mathrm{kg}$."), P4 + ", Q9(a)", sig=2)
    mcq_num(B, c, "Momentum and collisions", 2, "A bullet embeds in a block (bullet $12\\,\\mathrm{g}$, block $5.2\\,\\mathrm{kg}$). What fraction of the bullet's initial kinetic energy is dissipated?", frac, [m / (m + M), 0.5, 1 - frac, 0.1], "", ex("Fraction lost $=1-\\dfrac{\\tfrac12(m+M)v^2}{\\tfrac12mv_b^2}=\\dfrac{M}{m+M}=0.9977$: practically all of it."), P4 + ", Q9(b)", sig=4)
    # Q10 two-dimensional collision
    m1, m2, u1, th = 5.0, 2.5, 4.5, 30.0
    # y: m1 v1 sin = m2 v2 sin -> v2 = 2 v1 ; x: m1 u1 = (m1 v1 + m2 v2) cos
    v1f = m1 * u1 / ((m1 + 2 * m2) * math.cos(math.radians(th))); v2f = 2 * v1f
    K0 = 0.5 * m1 * u1 ** 2; K1 = 0.5 * m1 * v1f ** 2 + 0.5 * m2 * v2f ** 2
    check(K0, K1, 1e-9); check(m1 * v1f * math.sin(math.radians(th)), m2 * v2f * math.sin(math.radians(th)))
    mcq_num(B, c, "Momentum and collisions", 3, "A $5\\,\\mathrm{kg}$ object moving at $4.5\\,\\mathrm{m/s}$ hits a $2.5\\,\\mathrm{kg}$ object at rest on a frictionless surface. Afterwards both move at $30^\\circ$ on either side of the original line. What is the final speed of the $5\\,\\mathrm{kg}$ object?",
            v1f, [u1 / 2, v2f, u1 * math.cos(math.radians(th)), u1 * math.sin(math.radians(th))], "m/s", ex("$y$-momentum: $m_1v_1\\sin30^\\circ=m_2v_2\\sin30^\\circ\\Rightarrow v_2=2v_1$.", "$x$-momentum: $m_1u_1=(m_1v_1+m_2v_2)\\cos30^\\circ=10v_1\\cos30^\\circ\\Rightarrow v_1=\\dfrac{22.5}{8.66}=2.60\\,\\mathrm{m/s}$, $v_2=5.20\\,\\mathrm{m/s}$."), P4 + ", Q10(a)", sig=3)
    mcq_pick(B, c, "Momentum and collisions", 3, "For the same collision (5 kg at 4.5 m/s hits 2.5 kg at rest; final speeds $2.60$ and $5.20\\,\\mathrm{m/s}$ at $30^\\circ$ either side), is the collision elastic?",
             ["Yes: the total kinetic energy is $50.6\\,\\mathrm{J}$ before and after", "No: about half of the kinetic energy is lost", "No: momentum is not conserved in two dimensions", "Cannot be decided without the masses of the surfaces"], 0,
             ex("Before: $\\tfrac12(5)(4.5)^2=50.6\\,\\mathrm{J}$. After: $\\tfrac12(5)(2.60)^2+\\tfrac12(2.5)(5.20)^2=16.9+33.8=50.6\\,\\mathrm{J}$ - equal, so the collision is elastic."), P4 + ", Q10(b)", "src")
    # Q11 softball
    m, u, v, dt = 0.35, 12.0, 21.0, 0.01
    J = m * (v + u)
    mcq_num(B, c, "Impulse", 2, "A $0.35\\,\\mathrm{kg}$ softball pitched at $12\\,\\mathrm{m/s}$ is hit straight back at $21\\,\\mathrm{m/s}$. What impulse does the bat give the ball?", J, [m * (v - u), m * v, m * u, 2 * m * v], "N s", ex("Take the batted direction as positive: $J=\\Delta p=m(v_f-v_i)=0.35[21-(-12)]=11.6\\,\\mathrm{N\\,s}$. The velocity REVERSES, so the speeds add."), P4 + ", Q11(a)", sig=3)
    mcq_num(B, c, "Impulse", 2, "The bat in the previous problem acts on the ball for $0.01\\,\\mathrm{s}$ and gives it an impulse of $11.55\\,\\mathrm{N\\,s}$. What is the average force?", J / dt, [J / dt / 10, J * dt, m * (v - u) / dt, J / dt * 2], "N", ex("$\\bar F=\\dfrac{J}{\\Delta t}=\\dfrac{11.55}{0.01}=1.16\\times10^3\\,\\mathrm{N}$ (about $330$ times the weight of the ball)."), P4 + ", Q11(b)", sig=3)
    # ---------------------------------------------------------------- work, energy
    mcq_pick(B, c, "Work and energy", 1, "What is the main energy change while a light bulb operates?", ["chemical to heat", "electrical energy to heat and light", "heat and light to electrical energy", "electrical energy to kinetic energy"], 1, ex("A lamp transforms electrical energy into light and (mostly) heat."), P4 + ", Q12", "src")
    mcq_pick(B, c, "Work and energy", 1, "What are the main energy changes in a battery-operated remote-control car?", ["chemical to electrical to kinetic", "chemical to wave to kinetic", "wave to electrical to kinetic", "electrical to chemical to wave"], 0, ex("The battery stores chemical energy, which becomes electrical energy in the circuit, which the motor turns into kinetic energy (plus some heat)."), P4 + ", Q13", "src")
    eff = 6.0 * 40.0 / 500.0
    mcq_num(B, c, "Work and energy", 1, "A battery supplies $500\\,\\mathrm{J}$ of electrical energy to a motor which moves an object $40\\,\\mathrm{m}$ horizontally under a $6\\,\\mathrm{N}$ pulling force. What is the efficiency of the motor (as a percentage)?", eff * 100, [21.0, 75.0, 24.0, 12.0], "%", ex("Useful work $=Fd=6\\times40=240\\,\\mathrm{J}$.", "Efficiency $=\\dfrac{240}{500}=0.48=48\\%$."), P4 + ", Q14", sig=2)
    W = 5.0 * (14 - 3)
    mcq_num(B, c, "Work and energy", 1, "A particle is displaced from $\\vec r_1=(3\\hat i+2\\hat j-6\\hat k)\\,\\mathrm{m}$ to $\\vec r_2=(14\\hat i+13\\hat j+9\\hat k)\\,\\mathrm{m}$ by a force $5\\hat i\\,\\mathrm{N}$. How much work does the force do?", W, [65.0, 45.0, 75.0, 70.0], "J", ex("$W=\\vec F\\cdot\\Delta\\vec r$ with $\\Delta\\vec r=(11,11,15)\\,\\mathrm{m}$: only the $x$-component counts, $W=5\\times11=55\\,\\mathrm{J}$."), P4 + ", Q15", sig=2)
    # F-x graph (own numbers)
    pts = [(0, 0), (2, 3), (4, 3), (6, 0)]
    fig = figs.graph_vt(pts, "x (m)", "F (N)", "force-position graph: rises from 0 to 3 N over the first 2 m, constant 3 N until 4 m, falls to 0 at 6 m").svg()
    area = 0.5 * 2 * 3 + 2 * 3 + 0.5 * 2 * 3
    mcq_num(B, c, "Work and energy", 2, "A force $F$ acting on an object varies with position as shown. How much work does it do between $x=0$ and $x=6\\,\\mathrm{m}$?", area, [18.0, 9.0, 6.0, 15.0], "J", ex("Work $=$ area under the $F$-$x$ graph $=\\tfrac12(2)(3)+(2)(3)+\\tfrac12(2)(3)=3+6+3=12\\,\\mathrm{J}$."), GEN(P4 + ", Q16"), "gen", fig=fig, sig=3)
    h, x1, x2, T = 1.20, 3.00, 1.00, 25.0
    dK = T * (math.hypot(x1, h) - math.hypot(x2, h))
    check(dK, T * ((x1 ** 2 + h ** 2) - (x2 ** 2 + h ** 2)) / (math.hypot(x1, h) + math.hypot(x2, h)))
    mcq_num(B, c, "Work and energy", 3, "A cord, pulled over a pulley $h=1.20\\,\\mathrm{m}$ above the cart's level, drags a cart along a frictionless rail from $x_1=3.00\\,\\mathrm{m}$ to $x_2=1.00\\,\\mathrm{m}$. The cord tension is a constant $25.0\\,\\mathrm{N}$. What is the change in the kinetic energy of the cart?",
            dK, [T * (x1 - x2), 51.4, 33.7, 20.5], "J", ex("Work by the tension $=T\\times$ (decrease in the length of cord from the pulley to the cart).", "Length: $\\sqrt{x_1^2+h^2}=\\sqrt{10.44}=3.231\\,\\mathrm{m}$ and $\\sqrt{x_2^2+h^2}=\\sqrt{2.44}=1.562\\,\\mathrm{m}$.", "$\\Delta K=25.0(3.231-1.562)=41.7\\,\\mathrm{J}$. Using $T\\Delta x=50\\,\\mathrm{J}$ would ignore that the force is not horizontal."), P4 + ", Q17", sig=3)
    mcq_pick(B, c, "Work and energy", 2, "A ball is thrown off a cliff with the same initial speed $v_0$ (A) upward, (B) horizontally, (C) downward. If air resistance is negligible, how do the speeds on reaching the ground compare?", ["$v_A>v_B>v_C$", "$v_B>v_A>v_C$", "$v_A=v_C>v_B$", "$v_A=v_B=v_C$"], 3,
             ex("Gravity is conservative: the speed at the ground depends only on the starting speed and the height drop, $v=\\sqrt{v_0^2+2gh}$ - the same for every direction of launch."), P4 + ", Q19", "src")
    mcq_pick(B, c, "Work and energy", 2, "A ball of mass $m$ swings from height $h$ and collides elastically, at the lowest point, with a block of mass $2m$ at rest on a frictionless surface. To what height does the ball rise afterwards?", ["$h/9$", "$h/8$", "$h/3$", "$2h/3$"], 0,
             ex("Speed at the bottom $v=\\sqrt{2gh}$. Elastic collision: $v_{\\text{ball}}=\\dfrac{m-2m}{3m}v=-\\dfrac v3$. Its kinetic energy is $\\dfrac19$ of the original, so it rises to $h/9$."), P4 + ", Q20", "src")
    mcq_pick(B, c, "Work and energy", 2, "A block of mass $m$ slides down an incline at constant speed from height $h$ (coefficient of kinetic friction $\\mu$). How much energy is dissipated by friction by the time it reaches the bottom?", ["$mgh/\\mu$", "$mgh$", "$\\mu mgh/\\sin\\theta$", "$mgh\\sin\\theta$"], 1,
             ex("Constant speed means $\\Delta K=0$: all the gravitational potential energy lost, $mgh$, is converted to thermal energy (equivalently $f\\cdot L=mg\\sin\\theta\\,(h/\\sin\\theta)=mgh$)."), P4 + ", Q21", "src")
    m, h, th, mu = 3.0, 0.43, 35.0, 0.25
    d = h / mu - h / math.tan(math.radians(th))
    # second route: speed at the bottom, then deceleration on the flat
    L = h / math.sin(math.radians(th)); v2 = 2 * G * (h - mu * math.cos(math.radians(th)) * L); d2 = v2 / (2 * mu * G); check(d, d2)
    mcq_num(B, c, "Work and energy", 3, "A $3\\,\\mathrm{kg}$ block starts from rest at height $43\\,\\mathrm{cm}$ on a $35^\\circ$ incline, slides down, and then along a horizontal surface. The coefficient of kinetic friction is $0.25$ on both surfaces. How far does it slide on the horizontal surface before stopping?",
            d, [h / mu, h / mu + h / math.tan(math.radians(th)), h / math.tan(math.radians(th)), 2.0], "m", ex("Work-kinetic energy theorem over the whole path: $mgh-\\mu mg\\cos\\theta\\,\\dfrac{h}{\\sin\\theta}-\\mu mg\\,d=0$.", "$d=\\dfrac h\\mu-\\dfrac{h}{\\tan\\theta}=1.72-0.614=1.11\\,\\mathrm{m}$. (The mass cancels.)"), P4 + ", Q22", sig=3)
    m, L, th = 25.0, 2.0, 30.0
    hh = L * (1 - math.cos(math.radians(th))); U = m * G * hh; vlow = math.sqrt(2 * G * hh)
    check(U, 0.5 * m * vlow ** 2)
    mcq_num(B, c, "Potential energy and conservation", 2, "A $25\\,\\mathrm{kg}$ child on a $2.0\\,\\mathrm{m}$ long swing is released from rest with the supports at $30^\\circ$ to the vertical. What is the child's maximum gravitational potential energy (zero at the lowest point)?", U, [m * G * L, m * G * L * math.sin(math.radians(th)), m * G * hh * 2, U / 2], "J", ex("Height above the lowest point: $h=L(1-\\cos30^\\circ)=2.0(0.134)=0.268\\,\\mathrm{m}$.", "$U=mgh=25(9.8)(0.2679)=65.6\\,\\mathrm{J}$."), P4 + ", Q23(a)", sig=3)
    mcq_num(B, c, "Potential energy and conservation", 2, "The same swing: what is the child's speed at the lowest position if friction is disregarded?", vlow, [math.sqrt(2 * G * L), math.sqrt(G * hh), U / m, vlow * 2], "m/s", ex("Energy conservation: $\\tfrac12mv^2=mgh\\Rightarrow v=\\sqrt{2gh}=\\sqrt{2(9.8)(0.268)}=2.29\\,\\mathrm{m/s}$."), P4 + ", Q23(b)", sig=3)
    mcq_num(B, c, "Potential energy and conservation", 3, "The swing child ($25\\,\\mathrm{kg}$, released from a height $0.268\\,\\mathrm{m}$ above the lowest point) actually has speed $2.00\\,\\mathrm{m/s}$ at the lowest position. What is the change in mechanical energy due to friction?", 0.5 * m * 4.0 - U, [U, 0.5 * m * 4.0, U - 0.5 * m * 4.0, -2 * U], "J", ex("Final mechanical energy $=\\tfrac12(25)(2.00)^2=50.0\\,\\mathrm{J}$; initial $=65.6\\,\\mathrm{J}$.", "$\\Delta E=50.0-65.6=-15.6\\,\\mathrm{J}$ (15.6 J lost as heat)."), P4 + ", Q23(d)", sig=3)
    m, F, th, d, mu = 50.0, 95.0, 15.0, 6.0, 0.15
    Wp = F * d * math.cos(math.radians(th)); N = m * G - F * math.sin(math.radians(th)); fr = mu * N; Q = fr * d; vf = math.sqrt(2 * (Wp - Q) / m)
    mcq_num(B, c, "Work and energy", 3, "A pirate drags a $50\\,\\mathrm{kg}$ chest $6\\,\\mathrm{m}$ along a dock with a constant $95\\,\\mathrm{N}$ force $15^\\circ$ above the horizontal. How much work does the pirate do?", Wp, [F * d, F * d * math.sin(math.radians(th)), Wp - Q, 0.5 * F * d], "J", ex("$W=Fd\\cos\\theta=95(6)\\cos15^\\circ=551\\,\\mathrm{J}$."), P4 + ", Q24(a)", sig=3)
    mcq_num(B, c, "Work and energy", 3, "The pirate pulls the $50\\,\\mathrm{kg}$ chest at $15^\\circ$ above the horizontal with $95\\,\\mathrm{N}$ ($\\mu_k=0.15$, distance $6\\,\\mathrm{m}$). How much energy is dissipated as heat by friction?", Q, [mu * m * G * d, mu * (m * G + F * math.sin(math.radians(th))) * d, Wp, mu * F * d], "J", ex("The upward component of the pull reduces the normal force: $N=mg-F\\sin15^\\circ=490-24.6=465\\,\\mathrm{N}$.", "$Q=\\mu Nd=0.15(465)(6)=419\\,\\mathrm{J}$. (Using $N=mg$ would give $441\\,\\mathrm{J}$.)"), P4 + ", Q24(b)", sig=3)
    mcq_num(B, c, "Work and energy", 3, "The pirate's chest ($50\\,\\mathrm{kg}$) receives $551\\,\\mathrm{J}$ of work from the pull and loses $419\\,\\mathrm{J}$ to friction. What is its final speed (starting from rest)?", vf, [math.sqrt(2 * Wp / m), math.sqrt(2 * Q / m), (Wp - Q) / m, vf * 2], "m/s", ex("Work-energy theorem: $\\tfrac12mv^2=W_{\\text{net}}=551-419=132\\,\\mathrm{J}$, so $v=\\sqrt{\\dfrac{2(132)}{50}}=2.3\\,\\mathrm{m/s}$."), P4 + ", Q24(c)", sig=2)
    m, d1, th, d2 = 10.0, 3.00, 30.0, 5.00
    v = math.sqrt(2 * G * d1 * math.sin(math.radians(th))); mu = v ** 2 / (2 * G * d2); dE = -0.5 * m * v ** 2
    check(mu, d1 * math.sin(math.radians(th)) / d2)
    mcq_num(B, c, "Work and energy", 2, "Starting from rest, a $10.0\\,\\mathrm{kg}$ suitcase slides $3.00\\,\\mathrm{m}$ down a frictionless ramp inclined at $30.0^\\circ$. What is its speed at the bottom?", v, [math.sqrt(2 * G * d1), math.sqrt(G * d1 * math.sin(math.radians(th))), d1 * math.sin(math.radians(th)), v * 2], "m/s", ex("Height drop $=3.00\\sin30^\\circ=1.50\\,\\mathrm{m}$; $\\tfrac12mv^2=mgh\\Rightarrow v=\\sqrt{2(9.8)(1.50)}=5.42\\,\\mathrm{m/s}$."), P4 + ", Q25(a)", sig=3)
    mcq_num(B, c, "Work and energy", 3, "The suitcase then slides a further $5.00\\,\\mathrm{m}$ along the floor before stopping. What is the coefficient of kinetic friction on the floor?", mu, [d2 / d1, math.sin(math.radians(th)), 0.6, 0.15], "", ex("$\\tfrac12mv^2=\\mu mgd\\Rightarrow\\mu=\\dfrac{v^2}{2gd}=\\dfrac{29.4}{2(9.8)(5.00)}=0.300$. Equivalently all the potential energy $mg(1.5)$ is dissipated over $5.00\\,\\mathrm{m}$: $\\mu=1.5/5.0$."), P4 + ", Q25(b)", sig=3)
    mcq_num(B, c, "Work and energy", 2, "Using the same suitcase ($10.0\\,\\mathrm{kg}$, speed $5.42\\,\\mathrm{m/s}$ at the bottom of the ramp, then stopped on the floor), what is the change in mechanical energy due to friction on the floor?", dE, [-dE, 0.0, dE / 2, dE * 2], "J", ex("The suitcase loses all of its kinetic energy: $\\Delta E=0-\\tfrac12(10.0)(5.42)^2=-147\\,\\mathrm{J}$."), P4 + ", Q25(c)", sig=3)
    m1, m2, k, h = 2.0, 0.5, 40.0, 0.10
    mu = (m2 * G * h - 0.5 * k * h ** 2) / (m1 * G * h)
    mcq_text(B, c, "Work and energy", 3, "A block $m_1$ on a horizontal surface is joined to a spring of constant $k$ and, over a frictionless pulley, to a hanging block $m_2$. Released from rest with the spring unstretched, $m_2$ falls a distance $h$ before momentarily stopping. The coefficient of kinetic friction of $m_1$ is",
             "$\\mu=\\dfrac{m_2g-\\tfrac12kh}{m_1g}$", ["$\\mu=\\dfrac{m_2g-kh}{m_1g}$", "$\\mu=\\dfrac{m_2g}{m_1g}$", "$\\mu=\\dfrac{m_2g+\\tfrac12kh}{m_1g}$"],
             ex("Energy: lost potential energy of $m_2$ = spring energy + heat: $m_2gh=\\tfrac12kh^2+\\mu m_1gh$.", "$\\mu=\\dfrac{m_2g-\\tfrac12kh}{m_1g}$. The spring force is not constant, so its work is $\\tfrac12kh^2$, not $kh\\cdot h$."), P4 + ", Q26", "src")
    # ---------------------------------------------------------------- power
    mcq_pick(B, c, "Power", 1, "Which word equation correctly defines power?", ["force $\\times$ distance moved in the direction of the force", "force $\\times$ velocity", "work done $\\div$ time taken", "work done $\\times$ time taken"], 2, ex("Power is the rate of doing work, $P=W/t$. Option 1 is the work; option 2 is a formula that equals the power for a force along the velocity."), P4 + ", Q27", "src")
    mcq_pick(B, c, "Power", 1, "A body of mass $m$ is moved a distance $s$ at a steady speed $v$ against a constant force $F$. What power is required?", ["$mv$", "$\\tfrac12mv^2$", "$Fv$", "$Fs$"], 2, ex("$P=\\dfrac{Fs}{t}=Fv$."), P4 + ", Q28", "src")
    mcq_num(B, c, "Power", 1, "A car engine provides $24\\,\\mathrm{kW}$ of useful power to travel at constant speed. The driving force is $600\\,\\mathrm{N}$. What is the speed of the car?", 24000 / 600, [2.5, 4.0, 25, 14.4], "m/s", ex("$P=Fv\\Rightarrow v=\\dfrac{P}{F}=\\dfrac{24000}{600}=40\\,\\mathrm{m/s}$."), P4 + ", Q29", sig=2)
    P = (1000 + 1000 * 10) * 0.5
    mcq_num(B, c, "Power", 2, "A crane lifts its hook (steady force $1000\\,\\mathrm{N}$) together with a $1000\\,\\mathrm{kg}$ load at $0.5\\,\\mathrm{m/s}$ ($g=10\\,\\mathrm{m/s^2}$). What power is used?", P / 1000, [5.0, 20.0, 22.0, 11.0], "kW", ex("Total lifting force at constant velocity $=1000+1000(10)=11000\\,\\mathrm{N}$.", "$P=Fv=11000\\times0.5=5500\\,\\mathrm{W}=5.5\\,\\mathrm{kW}$."), P4 + ", Q30", sig=2)
    mcq_pick(B, c, "Power", 3, "A body of mass $m$ moves up a frictionless track inclined at $\\theta$ to the horizontal. What power is needed to give it a forward acceleration $a$ when its velocity is $v$?", ["$mav\\,g\\sin\\theta$", "$mav\\sin\\theta+mgv$", "$mav+mgv\\sin\\theta$", "$(mav+mgv)\\sin\\theta$"], 2,
             ex("Force along the track: $F=ma+mg\\sin\\theta$. Power $=Fv=mav+mgv\\sin\\theta$."), P4 + ", Q31", "src")
    # generated work / energy / power
    for m, F, d, th in [(4.0, 30.0, 5.0, 40.0), (10.0, 50.0, 8.0, 25.0)]:
        W = F * d * math.cos(math.radians(th))
        mcq_num(B, c, "Work and energy", 1, "A force of %s N pulls a %s kg sled %s m along level ice at %s° above the horizontal. How much work does the force do?" % (sci(F), sci(m), sci(d), sci(th)), W, [F * d, F * d * math.sin(math.radians(th)), W / 2, F * d / math.cos(math.radians(th))], "J",
                ex("$W=Fd\\cos\\theta=%s\\times%s\\times\\cos%s^\\circ=%s\\,\\mathrm{J}$. Only the component of the force along the displacement does work." % (sci(F), sci(d), sci(th), sci(W))), GEN(P4 + ", Q15"), "gen", sig=3)
    for m, v1, v2 in [(1200.0, 10.0, 25.0), (800.0, 5.0, 20.0)]:
        W = 0.5 * m * (v2 ** 2 - v1 ** 2)
        mcq_num(B, c, "Work and energy", 2, "How much net work must be done to speed a %s kg car up from %s m/s to %s m/s?" % (sci(m), sci(v1), sci(v2)), W, [0.5 * m * (v2 - v1) ** 2, m * (v2 - v1), 0.5 * m * v2 ** 2, 0.5 * m * (v2 ** 2 - v1 ** 2) / 2], "J",
                ex("Work-kinetic energy theorem: $W=\\tfrac12m(v_2^2-v_1^2)=\\tfrac12(%s)(%s^2-%s^2)=%s\\,\\mathrm{J}$." % (sci(m), sci(v2), sci(v1), sci(W)), "Do not square the difference of the speeds: $(v_2-v_1)^2\\ne v_2^2-v_1^2$."), GEN(P4 + ", Q17"), "gen", sig=3)
    for k, x in [(200.0, 0.15), (450.0, 0.08)]:
        Es = 0.5 * k * x ** 2
        mcq_num(B, c, "Potential energy and conservation", 1, "How much energy is stored in a spring of constant %s N/m compressed by %s m?" % (sci(k), sci(x)), Es, [k * x, k * x * x, 0.5 * k * x, Es * 2], "J", ex("$U=\\tfrac12kx^2=\\tfrac12(%s)(%s)^2=%s\\,\\mathrm{J}$." % (sci(k), sci(x), sci(Es))), GEN(P4 + ", Q26"), "gen", sig=3)
    for m, h in [(0.60, 12.0), (2.0, 7.5)]:
        v = math.sqrt(2 * G * h)
        mcq_num(B, c, "Potential energy and conservation", 1, "A %s kg ball is dropped from a height of %s m. Ignoring air resistance, what is its speed just before it hits the ground?" % (sci(m), sci(h)), v, [math.sqrt(G * h), m * G * h, 2 * G * h, v / 2], "m/s", ex("$mgh=\\tfrac12mv^2\\Rightarrow v=\\sqrt{2gh}=\\sqrt{2(9.8)(%s)}=%s\\,\\mathrm{m/s}$ (independent of the mass)." % (sci(h), sci(v))), GEN(P4 + ", Q19"), "gen", sig=3)
    for m, v, hf in [(0.5, 8.0, 0.0), (1.2, 6.0, 0.0)]:
        h = v * v / (2 * G)
        mcq_num(B, c, "Potential energy and conservation", 2, "A %s kg ball is thrown straight up at %s m/s. Use energy conservation to find the maximum height." % (sci(m), sci(v)), h, [v * v / G, v / G, m * v * v / 2, h / 2], "m", ex("$\\tfrac12mv^2=mgh\\Rightarrow h=\\dfrac{v^2}{2g}=\\dfrac{%s^2}{19.6}=%s\\,\\mathrm{m}$." % (sci(v), sci(h))), GEN(P4 + ", Q19"), "gen", sig=3)
    for m, t, h in [(60.0, 12.0, 15.0), (75.0, 8.0, 10.0)]:
        P_ = m * G * h / t
        mcq_num(B, c, "Power", 2, "A %s kg climber gains %s m of height in %s s at constant speed. What is the average power output against gravity?" % (sci(m), sci(h), sci(t)), P_, [m * G * h, m * h / t, m * G / t, P_ * 2], "W", ex("Work $=mgh=%s(9.8)(%s)=%s\\,\\mathrm{J}$.\nPower $=W/t=%s\\,\\mathrm{W}$." % (sci(m), sci(h), sci(m * G * h), sci(P_))), GEN(P4 + ", Q29-Q30"), "gen", sig=3)
    # ballistic pendulum
    m, M, h = 0.020, 1.5, 0.12
    vb = (m + M) / m * math.sqrt(2 * G * h)
    mcq_num(B, c, "Momentum and collisions", 3, "A ballistic pendulum: a $20\\,\\mathrm{g}$ bullet embeds in a $1.5\\,\\mathrm{kg}$ block hanging on strings, and the block swings up $12\\,\\mathrm{cm}$. What was the bullet's speed?", vb, [math.sqrt(2 * G * h), M / m * math.sqrt(2 * G * h), (m + M) * math.sqrt(2 * G * h), vb / 2], "m/s", ex("Swing (energy conservation): $v=\\sqrt{2gh}=\\sqrt{2(9.8)(0.12)}=1.53\\,\\mathrm{m/s}$ just after the collision.", "Collision (momentum): $mv_b=(m+M)v\\Rightarrow v_b=\\dfrac{1.52}{0.020}(1.53)=1.2\\times10^2\\,\\mathrm{m/s}$."), GEN(P4 + ", Q9"), "gen", sig=2)
    mcq_pick(B, c, "Work and energy", 2, "A force acts on an object that moves in a circle at constant speed, always along the radius towards the centre. How much work does this centripetal force do in one revolution?", ["Zero", "$2\\pi rF$", "$\\pi rF$", "$F\\,r$"], 0, ex("The force is perpendicular to the displacement at each instant ($\\cos90^\\circ=0$), so it does no work; the speed does not change."), "Lecture 4 (work done by a force)", "concept")
    mcq_pick(B, c, "Potential energy and conservation", 2, "Which of the following forces is NOT conservative?", ["gravity", "the spring force", "kinetic friction", "the electrostatic force"], 2, ex("The work of a conservative force depends only on the end points. Friction's work depends on the path length, so it is non-conservative (it dissipates mechanical energy)."), "Final tutorial (conservative and non-conservative forces)", "concept")
    mcq_pick(B, c, "Momentum and collisions", 2, "In a perfectly inelastic collision between two bodies,", ["momentum is conserved and the maximum possible kinetic energy is lost", "kinetic energy is conserved but momentum is not", "both momentum and kinetic energy are lost", "the bodies bounce apart with the same total kinetic energy"], 0, ex("The bodies stick together and move with the velocity of the centre of mass. Momentum is conserved; the kinetic energy that is lost is the largest possible while still conserving momentum."), "Final tutorial (types of collision)", "concept")

# =============================================================================================== chapter 4
def ch4(B):
    c = "c4"
    mcq_pick(B, c, "Uniform circular motion", 1, "A particle moves along a circular arc of length $\\ell$ and radius $r$ in time $t$. Which expression gives its angular velocity about the centre?", ["$\\dfrac{\\ell}{rt}$", "$\\dfrac{r}{\\ell t}$", "$\\dfrac{2\\pi}{\\ell t}$", "$\\dfrac{2\\pi r}{t}$"], 0, ex("Angle swept $\\theta=\\ell/r$, so $\\omega=\\dfrac\\theta t=\\dfrac{\\ell}{rt}$ (check: the linear speed $\\ell/t=\\omega r$)."), P5 + ", Q1", "src")
    mcq_pick(B, c, "Uniform circular motion", 1, "Particles P and Q are on a rotating circular plate; the distance of P from the axis is twice that of Q. What is (linear velocity of P) / (linear velocity of Q)?", ["4", "2", "1/2", "1/4"], 1, ex("Same $\\omega$ for every point of a rigid plate; $v=\\omega r$, so $v_P/v_Q=r_P/r_Q=2$."), P5 + ", Q2", "src")
    mcq_pick(B, c, "Uniform circular motion", 2, "A communication satellite moves at constant speed in a circular orbit around the Earth. Which row is correct for its momentum and kinetic energy?", ["momentum constant, kinetic energy changing", "momentum constant, kinetic energy constant", "momentum changing, kinetic energy changing", "momentum changing, kinetic energy constant"], 3,
             ex("Momentum $m\\vec v$ is a vector: its direction keeps changing, so it is not constant. Kinetic energy $\\tfrac12mv^2$ depends only on the (constant) speed."), P5 + ", Q3", "src")
    mcq_pick(B, c, "Uniform circular motion", 1, "Which statement is correct for a particle in a horizontal circle with constant angular velocity?", ["The linear momentum is constant but the kinetic energy varies", "The kinetic energy is constant but the linear momentum varies", "Both kinetic energy and linear momentum are constant", "Both speed and linear velocity are constant"], 1, ex("Speed (hence $K$) is constant; the velocity vector and momentum change direction."), P5 + ", Q4", "src")
    mcq_pick(B, c, "Uniform circular motion", 2, "A body in uniform circular motion has the following behaviour of linear velocity, angular velocity and linear acceleration:", ["constant, constant, varying", "constant, constant, zero", "constant, varying, constant", "varying, constant, varying"], 3,
             ex("Velocity is a vector whose direction rotates (varying); $\\omega$ is constant; the centripetal acceleration has constant magnitude but its direction rotates, so the acceleration vector varies."), P5 + ", Q5", "src")
    w = 2 * math.pi / 3600.0
    mcq_num(B, c, "Angular quantities", 1, "What is the mean angular speed of the minute hand of a clock?", w, [2 * math.pi / 60, 2 * math.pi / 86400, 1 / 3600, 0.1], "rad/s", ex("One revolution ($2\\pi\\,\\mathrm{rad}$) per $3600\\,\\mathrm{s}$: $\\omega=\\dfrac{2\\pi}{3600}=1.7\\times10^{-3}\\,\\mathrm{rad/s}$."), P5 + ", Q6", sig=2)
    mcq_pick(B, c, "Uniform circular motion", 2, "A spacecraft moves in a circular orbit when its engine fires, producing a force exactly equal and opposite to Earth's gravitational pull. How does the spacecraft move afterwards?", ["along a spiral path towards the Earth", "radially along the line to the Earth's centre", "along a tangent to the orbit", "in a circular orbit with a longer period"], 2, ex("Net force becomes zero, so Newton's first law applies: it continues in a straight line with its velocity at that instant, tangent to the circle."), P5 + ", Q7", "src")
    w = 3000 * 2 * math.pi / 60.0; r = 0.080; ac = w ** 2 * r
    check(ac, (w * r) ** 2 / r)
    mcq_num(B, c, "Uniform circular motion", 2, "An engine component rotates at $3000$ revolutions per minute in a circle of radius $8.0\\,\\mathrm{cm}$. What is its centripetal acceleration?", ac, [25, 3.1e4, 7.2e7, w * r], "m/s^2", ex("$\\omega=3000\\times\\dfrac{2\\pi}{60}=314\\,\\mathrm{rad/s}$.", "$a_c=\\omega^2r=(314)^2(0.080)=7.9\\times10^{3}\\,\\mathrm{m/s^2}$ (convert $8.0\\,\\mathrm{cm}$ to $0.080\\,\\mathrm{m}$)."), P5 + ", Q8", sig=2)
    m, Lp, v = 1.27, 0.600, 0.575
    T = m * 9.81 + m * v ** 2 / Lp
    mcq_num(B, c, "Dynamics of circular motion", 2, "A pendulum bob of mass $1.27\\,\\mathrm{kg}$ hangs from a string of length $0.600\\,\\mathrm{m}$. When the string is vertical the bob moves horizontally at $0.575\\,\\mathrm{m/s}$. What is the tension in the string? ($g=9.81\\,\\mathrm{m/s^2}$)",
            T, [11.8, 12.5, 13.7, m * 9.81], "N", ex("At the lowest point the net force is centripetal (upwards): $T-mg=\\dfrac{mv^2}{L}$.", "$T=mg+\\dfrac{mv^2}{L}=12.46+0.70=13.2\\,\\mathrm{N}$."), P5 + ", Q9", sig=3)
    mcq_pick(B, c, "Dynamics of circular motion", 2, "A pendulum bob of mass $m$ and weight $W$ swings on a string of length $r$. When the string is vertical the tension is $T$ and the speed is $v$. Which relation is correct?", ["$T=W$", "$T-W=v^2/r$", "$T-W=mv^2/r$", "$W-T=mv^2/r$"], 2, ex("Net force towards the centre (upwards) is $T-W=\\dfrac{mv^2}{r}$. Option 2 has the wrong dimensions (missing the mass)."), P5 + ", Q10", "src")
    mcq_pick(B, c, "Dynamics of circular motion", 2, "A car of mass $m$ travels at constant speed $v$ over a humpback bridge of radius $r$ and stays in contact with the road. The force it exerts on the road at the top is", ["$R=mg+mv^2/r$", "$R=mv^2/r$", "$R=mg-mv^2/r$", "$R=mv^2/r-mg$"], 2, ex("Centre of curvature is below: $mg-N=\\dfrac{mv^2}{r}\\Rightarrow N=mg-\\dfrac{mv^2}{r}$, and the car pushes on the road with the same force $R$ (third law). The car loses contact when $v=\\sqrt{gr}$."), P5 + ", Q11", "src")
    # loop the loop minimum height
    R = 0.50; h = 2.5 * R
    v_top2 = G * R; h2 = 2 * R + v_top2 / (2 * G); check(h, h2)
    mcq_pick(B, c, "Dynamics of circular motion", 3, "A body is released from rest at height $h$ on a frictionless incline that leads into a vertical loop of radius $R$. What is the minimum $h$ for the body to complete the loop?", ["$6.0R$", "$4.0R$", "$2.5R$", "$2.0R$"], 2,
             ex("At the top of the loop the normal force can be zero at best: $mg=\\dfrac{mv^2}{R}\\Rightarrow v^2=gR$.", "Energy from the release point to the top: $mgh=mg(2R)+\\tfrac12mv^2=2mgR+\\tfrac12mgR$, so $h=2.5R$."), P5 + ", Q12", "src")
    # Lecture 5 exercises
    m, r, rpm = 25.0, 5.00, 5.0
    w = rpm * 2 * math.pi / 60; F = m * w ** 2 * r
    check(F, m * (w * r) ** 2 / r)
    mcq_num(B, c, "Dynamics of circular motion", 2, "A $25.0\\,\\mathrm{kg}$ sled on frictionless ice is tied by a $5.00\\,\\mathrm{m}$ rope to a post and revolves uniformly, making five complete revolutions every minute. What force does the rope exert on it?", F, [m * w * r, m * w ** 2 * r / 2, m * (rpm / 60) ** 2 * r, m * w ** 2], "N", ex("$\\omega=\\dfrac{5(2\\pi)}{60}=0.524\\,\\mathrm{rad/s}$.", "Rope tension supplies the centripetal force: $F=m\\omega^2r=25.0(0.524)^2(5.00)=34.3\\,\\mathrm{N}$."), "Lecture 5, Exercise 1", sig=3)
    mu, R_, = 0.70, 50.0
    v = math.sqrt(mu * G * R_)
    mcq_num(B, c, "Dynamics of circular motion", 2, "A car rounds a flat unbanked curve of radius $50.0\\,\\mathrm{m}$. The coefficient of static friction between tyres and road is $0.70$. What is the maximum speed without sliding?", v, [mu * G * R_, math.sqrt(mu * R_), math.sqrt(2 * mu * G * R_), v / 2], "m/s", ex("Friction supplies the centripetal force: $\\mu mg\\ge\\dfrac{mv^2}{R}\\Rightarrow v_{\\max}=\\sqrt{\\mu gR}=\\sqrt{0.70(9.8)(50.0)}=18.5\\,\\mathrm{m/s}$ ($\\approx67\\,\\mathrm{km/h}$)."), "Lecture 5, Exercise 2", sig=3)
    # generated circular motion
    for v, R_ in [(20.0, 80.0), (12.0, 30.0)]:
        a = v * v / R_
        mcq_num(B, c, "Uniform circular motion", 1, "A car moves at %s m/s round a circular track of radius %s m. What is its centripetal acceleration?" % (sci(v), sci(R_)), a, [v / R_, v * v * R_, v * R_, a * 2], "m/s^2", ex("$a_c=\\dfrac{v^2}{r}=\\dfrac{%s^2}{%s}=%s\\,\\mathrm{m/s^2}$." % (sci(v), sci(R_), sci(a))), GEN(P5 + ", Q8"), "gen", sig=3)
    for T_, r_ in [(2.0, 0.50), (0.25, 0.10)]:
        v = 2 * math.pi * r_ / T_; a = 4 * math.pi ** 2 * r_ / T_ ** 2
        check(a, v * v / r_)
        mcq_num(B, c, "Uniform circular motion", 2, "A stone on a string moves in a horizontal circle of radius %s m with a period of %s s. What is its centripetal acceleration?" % (sci(r_), sci(T_)), a, [v, 2 * math.pi * r_ / T_ ** 2, 4 * math.pi ** 2 * r_ / T_, a / 2], "m/s^2", ex("$a_c=\\dfrac{4\\pi^2r}{T^2}=\\dfrac{4\\pi^2(%s)}{%s^2}=%s\\,\\mathrm{m/s^2}$.\nSecond route: $v=2\\pi r/T=%s\\,\\mathrm{m/s}$ and $a_c=v^2/r$ gives the same value." % (sci(r_), sci(T_), sci(a), sci(v))), GEN(P5 + ", Q8"), "gen", sig=3)
    for m, v, r_ in [(0.80, 5.0, 1.2), (2.0, 3.0, 0.60)]:
        Tt = m * v * v / r_; Tb = Tt + m * G; Ttop = Tt - m * G
        mcq_num(B, c, "Dynamics of circular motion", 3, "A %s kg object whirled on a string in a VERTICAL circle of radius %s m has speed %s m/s at the lowest point. What is the tension there?" % (sci(m), sci(r_), sci(v)), Tb, [Tt, Ttop, m * G, Tb + m * G], "N", ex("Lowest point, centre above: $T-mg=\\dfrac{mv^2}{r}\\Rightarrow T=m\\left(g+\\dfrac{v^2}{r}\\right)=%s\\,\\mathrm{N}$." % sci(Tb), "At the lowest point the tension is the largest; the weight adds to the centripetal requirement."), GEN(P5 + ", Q9"), "gen", sig=3)
    for R_ in (0.80, 2.0):
        vmin = math.sqrt(G * R_)
        mcq_num(B, c, "Dynamics of circular motion", 3, "What is the minimum speed at the TOP of a vertical circle of radius %s m for an object on a string to keep the string taut?" % sci(R_), vmin, [math.sqrt(2 * G * R_), math.sqrt(5 * G * R_), G * R_, vmin / 2], "m/s", ex("At the minimum speed the tension vanishes: $mg=\\dfrac{mv^2}{R}\\Rightarrow v=\\sqrt{gR}=%s\\,\\mathrm{m/s}$." % sci(vmin), "The matching minimum speed at the bottom is $\\sqrt{5gR}$ (energy conservation)."), GEN(P5 + ", Q12"), "gen", sig=3)
    # banked curve
    v, R_ = 20.0, 100.0
    th = math.degrees(math.atan(v * v / (G * R_)))
    mcq_num(B, c, "Dynamics of circular motion", 3, "A frictionless banked curve of radius $100\\,\\mathrm{m}$ is designed for $20\\,\\mathrm{m/s}$. What is the banking angle?", th, [math.degrees(math.asin(v * v / (G * R_))), math.degrees(math.atan(v / (G * R_))), 45.0, 2 * th], "deg", ex("Only the horizontal component of the normal force supplies the centripetal force: $N\\sin\\theta=\\dfrac{mv^2}{R}$, $N\\cos\\theta=mg$.", "$\\tan\\theta=\\dfrac{v^2}{gR}=\\dfrac{400}{980}=0.408\\Rightarrow\\theta=22.2^\\circ$."), "Lecture 5 (dynamics of circular motion)", "gen", sig=3)
    # rotation kinematics
    for w0, al, t in [(0.0, 2.0, 5.0), (4.0, 3.0, 6.0)]:
        wf = w0 + al * t; th_ = w0 * t + 0.5 * al * t * t
        check(wf ** 2, w0 ** 2 + 2 * al * th_)
        mcq_num(B, c, "Rotation of rigid bodies", 2, "A wheel starting at angular speed %s rad/s has a constant angular acceleration of %s rad/s². What is its angular speed after %s s?" % (sci(w0), sci(al), sci(t)), wf, [al * t / 2 + w0, w0 + al * t * t / 2, w0 * t, wf * 2], "rad/s", ex("$\\omega=\\omega_0+\\alpha t=%s+%s\\times%s=%s\\,\\mathrm{rad/s}$." % (sci(w0), sci(al), sci(t), sci(wf))), GEN("Lecture 5 (rotation with constant angular acceleration)"), "gen", sig=3)
        mcq_num(B, c, "Rotation of rigid bodies", 2, "A wheel starting at %s rad/s has constant angular acceleration %s rad/s². Through what angle does it turn in %s s?" % (sci(w0), sci(al), sci(t)), th_, [wf * t, w0 * t, (w0 + wf) * t, th_ / 2], "rad", ex("$\\theta=\\omega_0t+\\tfrac12\\alpha t^2=%s\\,\\mathrm{rad}$. Check: $\\omega^2=\\omega_0^2+2\\alpha\\theta$ gives the same angle." % sci(th_)), GEN("Lecture 5 (rotation with constant angular acceleration)"), "gen", sig=3)
    r_, w, al = 0.25, 8.0, 3.0
    at = al * r_; ar = w * w * r_; atot = math.hypot(at, ar)
    mcq_num(B, c, "Rotation of rigid bodies", 3, "A point on a rotating disk is $0.25\\,\\mathrm{m}$ from the axis. At an instant the disk has $\\omega=8.0\\,\\mathrm{rad/s}$ and $\\alpha=3.0\\,\\mathrm{rad/s^2}$. What is the magnitude of the point's total linear acceleration?", atot, [at + ar, ar, at, math.hypot(w * r_, at)], "m/s^2", ex("Tangential: $a_t=\\alpha r=0.75\\,\\mathrm{m/s^2}$. Radial (centripetal): $a_r=\\omega^2r=16.0\\,\\mathrm{m/s^2}$.", "They are perpendicular: $a=\\sqrt{0.75^2+16.0^2}=16.0\\,\\mathrm{m/s^2}$."), "Lecture 5 (linear acceleration in rigid-body rotation)", "gen", sig=3)
    mcq_num(B, c, "Angular quantities", 1, "A flywheel turns at $1200$ revolutions per minute. Express its angular speed in rad/s.", 1200 * 2 * math.pi / 60, [1200 / 60, 1200 * 2 * math.pi, 1200 / (2 * math.pi), 1200 * math.pi / 60], "rad/s", ex("$\\omega=1200\\times\\dfrac{2\\pi\\,\\mathrm{rad}}{60\\,\\mathrm{s}}=126\\,\\mathrm{rad/s}$."), "Lecture 5 (angular velocity)", sig=3, origin="gen")
    mcq_num(B, c, "Angular quantities", 2, "A wheel of radius $0.30\\,\\mathrm{m}$ rolls without slipping at $6.0\\,\\mathrm{m/s}$. Through how many revolutions does it turn in $10\\,\\mathrm{s}$?", 6.0 * 10 / (2 * math.pi * 0.30), [6.0 * 10 / 0.30, 6.0 * 10, 6.0 * 10 / (math.pi * 0.30), 2 * math.pi * 6.0 * 10 / 0.30], "rev", ex("Distance rolled $=60\\,\\mathrm{m}$; one revolution covers the circumference $2\\pi(0.30)=1.885\\,\\mathrm{m}$.", "Revolutions $=\\dfrac{60}{1.885}=31.8$."), "Lecture 5 (relating linear and angular kinematics)", sig=3, origin="gen")
    mcq_pick(B, c, "Angular quantities", 1, "The SI unit of angular velocity is", ["rad/s", "rev/min", "m/s", "degree"], 0, ex("$\\omega=\\Delta\\theta/\\Delta t$ in radians per second (rev/min is a common non-SI unit)."), "Lecture 5 (angular velocity)", "concept")
    mcq_pick(B, c, "Uniform circular motion", 1, "In uniform circular motion the centripetal acceleration is directed", ["towards the centre of the circle", "away from the centre", "along the velocity", "opposite to the velocity"], 0, ex("The acceleration changes the direction, not the magnitude, of the velocity, so it is perpendicular to $\\vec v$ and points inward: $a_c=v^2/r$."), "Lecture 5 (uniform circular motion)", "concept")
    mcq_pick(B, c, "Dynamics of circular motion", 2, "A coin rests on a turntable that spins faster and faster. The coin finally slides off. Which force provides the coin's centripetal force until then?", ["static friction", "its weight", "the normal force", "centrifugal force"], 0, ex("Static friction acting towards the centre; it can only supply $\\mu_smg$, so the coin slips when $m\\omega^2r>\\mu_smg$. 'Centrifugal force' is not a real force in an inertial frame."), "Lecture 5 (dynamics of circular motion)", "concept")
    mcq_num(B, c, "Dynamics of circular motion", 2, "A $0.50\\,\\mathrm{kg}$ ball on a $1.0\\,\\mathrm{m}$ string moves in a horizontal circle at $4.0\\,\\mathrm{m/s}$ on a frictionless table. What is the tension?", 0.50 * 16 / 1.0, [0.5 * 4.0, 0.5 * 9.8, 0.5 * 4.0 / 1.0 * 4, 16.0], "N", ex("$T=\\dfrac{mv^2}{r}=\\dfrac{0.50(16)}{1.0}=8.0\\,\\mathrm{N}$."), GEN(P5 + ", Q9"), sig=2, origin="gen")

    # ---------------------------------------------------------------- more circular motion and rotation
    R_, T_, m = 12.0, 20.0, 60.0
    v = 2 * math.pi * R_ / T_; ac = v * v / R_
    check(ac, 4 * math.pi ** 2 * R_ / T_ ** 2)
    mcq_num(B, c, "Dynamics of circular motion", 3, "A rider of mass $60\\,\\mathrm{kg}$ sits on a Ferris wheel of radius $12\\,\\mathrm{m}$ that makes one revolution every $20\\,\\mathrm{s}$. What is the normal force of the seat on the rider at the TOP of the ride?", m * (G - ac), [m * (G + ac), m * G, m * ac, m * (G - ac) * 1.5], "N",
            ex("Speed $v=\\dfrac{2\\pi R}{T}=3.77\\,\\mathrm{m/s}$, so $a_c=\\dfrac{v^2}{R}=1.18\\,\\mathrm{m/s^2}$ (towards the centre, i.e. downwards at the top).", "$mg-N=ma_c\\Rightarrow N=m(g-a_c)=60(9.8-1.18)=517\\,\\mathrm{N}$: the rider feels lighter at the top (and heavier, $659\\,\\mathrm{N}$, at the bottom)."), GEN(P5 + ", Q11"), "gen", sig=3)
    mcq_num(B, c, "Dynamics of circular motion", 3, "The same rider ($60\\,\\mathrm{kg}$) on a Ferris wheel of radius $12\\,\\mathrm{m}$ with period $20\\,\\mathrm{s}$: what does the seat push with at the BOTTOM of the ride?", m * (G + ac), [m * (G - ac), m * G, m * ac, m * G + m * v], "N",
            ex("At the bottom the centre is above: $N-mg=ma_c\\Rightarrow N=m(g+a_c)=60(9.8+1.18)=659\\,\\mathrm{N}$."), GEN(P5 + ", Q9"), "gen", sig=3)
    L, th = 1.5, 30.0
    r_ = L * math.sin(math.radians(th)); T1 = 2 * math.pi * math.sqrt(L * math.cos(math.radians(th)) / G)
    v_ = math.sqrt(G * r_ * math.tan(math.radians(th))); T2 = 2 * math.pi * r_ / v_
    check(T1, T2)
    mcq_num(B, c, "Dynamics of circular motion", 3, "A conical pendulum has a string of length $1.5\\,\\mathrm{m}$ making $30^\\circ$ with the vertical. What is the period of its horizontal circular motion?", T1, [2 * math.pi * math.sqrt(L / G), 2 * math.pi * math.sqrt(L * math.sin(math.radians(th)) / G), 2 * math.pi * math.sqrt(L * math.cos(math.radians(th)) / G) * 2, 2 * math.pi * L / G],
            "s", ex("Vertical: $T\\cos\\theta=mg$. Horizontal: $T\\sin\\theta=m\\omega^2r$ with $r=L\\sin\\theta$. Dividing, $\\omega^2=\\dfrac{g}{L\\cos\\theta}$.", "$T=2\\pi\\sqrt{\\dfrac{L\\cos\\theta}{g}}=2\\pi\\sqrt{\\dfrac{1.5(0.866)}{9.8}}=2.29\\,\\mathrm{s}$. Check: $v=\\sqrt{gr\\tan\\theta}=2.06\\,\\mathrm{m/s}$ and $T=2\\pi r/v=2.29\\,\\mathrm{s}$."), GEN("Lecture 5 (dynamics of circular motion)"), "gen", sig=3)
    mu, R_ = 0.40, 3.0
    w = math.sqrt(G / (mu * R_))
    mcq_num(B, c, "Dynamics of circular motion", 3, "In a rotor ride a person is pressed against the vertical wall of a cylinder of radius $3.0\\,\\mathrm{m}$ (coefficient of static friction $0.40$). What is the minimum angular speed that stops the person from sliding down?", w, [math.sqrt(G / R_), G / (mu * R_), math.sqrt(mu * G / R_), w * 2], "rad/s",
            ex("Vertical: friction holds the weight, $\\mu N\\ge mg$. Horizontal: the wall's normal force supplies the centripetal force, $N=m\\omega^2R$.", "$\\mu\\omega^2R\\ge g\\Rightarrow\\omega\\ge\\sqrt{\\dfrac{g}{\\mu R}}=\\sqrt{\\dfrac{9.8}{0.40(3.0)}}=2.86\\,\\mathrm{rad/s}$ (about $27\\,\\mathrm{rpm}$)."), GEN("Lecture 5 (dynamics of circular motion)"), "gen", sig=3)
    R_ = 40.0
    mcq_num(B, c, "Dynamics of circular motion", 3, "A car crosses the top of a circular hill of radius $40\\,\\mathrm{m}$. What is the greatest speed at which the tyres stay in contact with the road?", math.sqrt(G * R_), [math.sqrt(2 * G * R_), G * R_, math.sqrt(G * R_ / 2), math.sqrt(G / R_)], "m/s", ex("The road's push vanishes when the whole weight is needed for the centripetal force: $mg=\\dfrac{mv^2}{R}\\Rightarrow v=\\sqrt{gR}=\\sqrt{9.8(40)}=19.8\\,\\mathrm{m/s}$."), GEN(P5 + ", Q11"), "gen", sig=3)
    m_, v_, R_ = 0.50, 6.0, 1.0
    mcq_num(B, c, "Dynamics of circular motion", 3, "A $0.50\\,\\mathrm{kg}$ ball on a $1.0\\,\\mathrm{m}$ string is whirled in a vertical circle and has speed $6.0\\,\\mathrm{m/s}$ at the top. What is the tension at the top?", m_ * (v_ ** 2 / R_ - G), [m_ * (v_ ** 2 / R_ + G), m_ * v_ ** 2 / R_, m_ * G, m_ * (v_ ** 2 / R_ - G) * 2], "N", ex("Both tension and weight point towards the centre at the top: $T+mg=\\dfrac{mv^2}{R}\\Rightarrow T=0.50\\left(\\dfrac{36}{1.0}-9.8\\right)=13.1\\,\\mathrm{N}$."), GEN(P5 + ", Q10"), "gen", sig=3)
    w0, al = 40.0, -5.0
    t = -w0 / al; rev = (w0 ** 2 / (2 * -al)) / (2 * math.pi)
    check(w0 * t + 0.5 * al * t * t, w0 ** 2 / (2 * -al))
    mcq_num(B, c, "Rotation of rigid bodies", 2, "A grinding wheel spinning at $40\\,\\mathrm{rad/s}$ is slowed by friction with a constant angular acceleration of $-5.0\\,\\mathrm{rad/s^2}$. How many revolutions does it make before it stops?", rev, [w0 ** 2 / (2 * 5.0), w0 / 5.0, w0 * t / (2 * math.pi), rev * 2], "rev", ex("$\\omega^2=\\omega_0^2+2\\alpha\\theta\\Rightarrow\\theta=\\dfrac{40^2}{2(5.0)}=160\\,\\mathrm{rad}$.", "Revolutions $=\\dfrac{160}{2\\pi}=25.5$. Time to stop $=8.0\\,\\mathrm{s}$; check $\\theta=\\tfrac12\\omega_0t=160\\,\\mathrm{rad}$."), GEN("Lecture 5 (rotation with constant angular acceleration)"), "gen", sig=3)
    w1, w2, t = 300 * 2 * math.pi / 60, 900 * 2 * math.pi / 60, 6.0
    al = (w2 - w1) / t
    mcq_num(B, c, "Rotation of rigid bodies", 2, "A disk speeds up uniformly from $300$ rpm to $900$ rpm in $6.0\\,\\mathrm{s}$. What is its angular acceleration?", al, [(900 - 300) / 6.0, (900 - 300) / 6.0 * 2 * math.pi, al / 2, (w2 + w1) / t], "rad/s^2", ex("Convert first: $300\\,\\mathrm{rpm}=31.4\\,\\mathrm{rad/s}$, $900\\,\\mathrm{rpm}=94.2\\,\\mathrm{rad/s}$.", "$\\alpha=\\dfrac{94.2-31.4}{6.0}=10.5\\,\\mathrm{rad/s^2}$."), GEN("Lecture 5 (angular acceleration)"), "gen", sig=3)
    Re, Td = 6.37e6, 86400.0
    mcq_num(B, c, "Angular quantities", 2, "A point on the Earth's equator (radius $6.37\\times10^{6}\\,\\mathrm{m}$) moves in a circle once every $24\\,\\mathrm{h}$. What is its speed due to the Earth's rotation?", 2 * math.pi * Re / Td, [Re / Td, 2 * math.pi * Re / 24, 2 * math.pi / Td, math.pi * Re / Td], "m/s", ex("$v=\\omega R=\\dfrac{2\\pi}{86400}(6.37\\times10^{6})=463\\,\\mathrm{m/s}$ (about $1670\\,\\mathrm{km/h}$)."), GEN("Lecture 5 (relating linear and angular kinematics)"), "gen", sig=3)
    mcq_num(B, c, "Angular quantities", 1, "A bicycle wheel of radius $0.35\\,\\mathrm{m}$ turns through $3.2\\,\\mathrm{rad}$. How far does a point on the rim travel along its circular path?", 0.35 * 3.2, [0.35 / 3.2, 3.2 / 0.35, 2 * math.pi * 0.35, 0.35 * 3.2 * 2], "m", ex("$s=r\\theta=0.35\\times3.2=1.12\\,\\mathrm{m}$ (the angle must be in radians)."), GEN("Lecture 5 (angular velocity)"), "gen", sig=3)
    mcq_pick(B, c, "Dynamics of circular motion", 2, "A car goes round a level curve at constant speed. If the speed is doubled, the friction force needed to keep it on the same curve is multiplied by", ["4", "2", "1/2", "1"], 0, ex("$f=\\dfrac{mv^2}{R}$: it grows with the square of the speed, so doubling $v$ needs four times the friction (which is why the maximum safe speed $\\sqrt{\\mu gR}$ matters)."), "Lecture 5, Exercise 2", "concept")
    mcq_pick(B, c, "Uniform circular motion", 2, "If the radius of a circular path is doubled while the speed stays the same, the centripetal acceleration", ["is halved", "is doubled", "stays the same", "is multiplied by four"], 0, ex("$a_c=\\dfrac{v^2}{r}$: with $v$ fixed it is inversely proportional to $r$."), "Lecture 5 (uniform circular motion)", "concept")
    mcq_pick(B, c, "Uniform circular motion", 2, "A particle moves in a circle with constant speed. The angle between its velocity and its acceleration is", ["$90^\\circ$", "$0^\\circ$", "$180^\\circ$", "$45^\\circ$"], 0, ex("Constant speed means no tangential acceleration; the only acceleration is centripetal, perpendicular ($90^\\circ$) to the velocity."), "Lecture 5 (uniform circular motion)", "concept")
